#!/usr/bin/env node
// Embeds rendering/shaders/*.glsl|*.wgsl into rendering/web/src/shaders.generated.ts.
// `--check` verifies the generated file is current (CI).
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "rendering/shaders");
const files = readdirSync(dir).filter((f) => /\.(glsl|wgsl)$/.test(f)).sort();
const entries = files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(join(dir, f), "utf8"))},`);
const out = `// GENERATED by scripts/gen-shaders.mjs from rendering/shaders — do not edit.\nexport const SHADER_SOURCES: Record<string, string> = {\n${entries.join("\n")}\n};\n`;
const target = join(root, "rendering/web/src/shaders.generated.ts");
if (process.argv.includes("--check")) {
  if (readFileSync(target, "utf8") !== out) {
    console.error("shaders.generated.ts is out of date; run `node scripts/gen-shaders.mjs`.");
    process.exit(1);
  }
  console.log("shaders.generated.ts is up to date");
} else {
  writeFileSync(target, out);
  console.log(`wrote ${files.length} shaders → ${target}`);
}
